export type PublicationStatus = 'draft' | 'review' | 'published';

export interface Article {
    publicationStatus: PublicationStatus;
    indexable: boolean;
    /**
     * Stable Publication identity (SiteOS Phase 3 Batch 2), independent of
     * slug/publicPath: assigned once at migration/creation time and never
     * recomputed from the current slug, so a future rename does not change
     * identity. Optional during the migration window - every article
     * currently in ARTICLES has one; src/siteos/compat/articleToPublication.ts
     * falls back to a slug-derived id only when absent. New articles should
     * always be given an id at ingestion time.
     */
    id?: string;
    slug: string;
    publicPath: string;
    title: string;
    subtitle?: string;
    seoTitle: string;
    description: string;
    keywords: string[];
    category: string;
    tags: string[];
    datePublished: string;
    dateModified: string;
    readTime: string;
    author: {
        name: string;
        role: string;
    };
    canonicalUrl: string;
    markdownUrl: string;
    heroSummary: string;
    keyTakeaway: string;
    heroBadge?: string;
    cardCta?: string;
    coverImage?: {
        src: string;
        alt: string;
        /**
         * SiteOS accessibility governance (backward-compatible addition):
         * see ArticleSection['image'].decorative above. A cover image is
         * almost never purely decorative (it also drives OG/Twitter image
         * alt text in SEOHead.tsx), so this exists purely as an explicit,
         * reviewable authoring decision rather than a silent default.
         */
        decorative?: boolean;
    };
    interactiveTheme?: boolean;
    cta?: {
        title: string;
        description: string;
        buttonText: string;
        buttonLink: string;
        whatsappText?: string;
    };
    sections: ArticleSection[];
    faqs?: FAQItem[];
    conversionConfig?: ArticleConversionConfig;
}

